async function requireOwner(req, res, next) {
  try {
    if (isAgentBypass(req)) {
      const r = bypassRole(req);
      if (r === "admin" || r === "owner") {
        applyBypassToReq(req);
        next();
        return;
      }
      res.status(403).json({ error: "Forbidden \u2013 owner or admin only (bypass role mismatch)" });
      return;
    }
    const { userId } = getAuth(req);
    if (!userId) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    const role = await getUserRole(userId);
    if (role !== "admin" && role !== "owner") {
      res.status(403).json({ error: "Forbidden \u2013 owner or admin only" });

