// GET /courts/:id/pricing-rules  — get special pricing rules (holiday rate, etc.)
router.get("/courts/:id/pricing-rules", async (req, res): Promise<void> => {
  const courtId = Number(String(req.params.id));
  if (isNaN(courtId)) { res.status(400).json({ error: "Invalid courtId" }); return; }

  const rules = await db
    .select()
    .from(courtPricingRulesTable)
    .where(eq(courtPricingRulesTable.courtId, courtId));

  res.json(rules.map(r => ({ id: r.id, type: r.type, price: Number(r.price) })));
});

// PUT /courts/:id/pricing-rules  — upsert special pricing rules (owner only)
router.put("/courts/:id/pricing-rules", requireAuth, async (req, res): Promise<void> => {
  const courtId = Number(String(req.params.id));
  if (isNaN(courtId)) { res.status(400).json({ error: "Invalid courtId" }); return; }

  const { rules } = req.body as { rules: Array<{ type: string; price: number }> };
  if (!Array.isArray(rules)) { res.status(400).json({ error: "rules must be an array" }); return; }

  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, courtId));
  if (!court) { res.status(404).json({ error: "Court not found" }); return; }

  const facility = await getFacility(court.facilityId);
  if (!(await isOwner(req, facility?.ownerUserId ?? null))) {
    res.status(403).json({ error: "Forbidden" }); return;
  }

  // Replace all rules for this court
  await db.delete(courtPricingRulesTable).where(eq(courtPricingRulesTable.courtId, courtId));

  if (rules.length > 0) {
    await db.insert(courtPricingRulesTable).values(
      rules.map(r => ({
        courtId,
        type: r.type,
        price: String(r.price),
      }))
    );
  }

  const updated = await db
    .select()
    .from(courtPricingRulesTable)
    .where(eq(courtPricingRulesTable.courtId, courtId));

  res.json(updated.map(r => ({ id: r.id, type: r.type, price: Number(r.price) })));
});

