170	  const selCount = sel.size;
171	
172	  // ── Mouse handlers ────────────────────────────────────────────────────────
173	  function handleCellMouseDown(dIdx: number, tIdx: number, e: React.MouseEvent) {
174	    e.preventDefault();
175	    setDragStart({ d: dIdx, t: tIdx });
176	    setDragEnd({ d: dIdx, t: tIdx });
177	    setIsDragging(true);
178	  }
179	
