181	    if (!isDragging) return;
182	    setDragEnd({ d: dIdx, t: tIdx });
183	  }
184	
185	  useEffect(() => {
186	    const up = () => setIsDragging(false);
187	    window.addEventListener("mouseup", up);
188	    return () => window.removeEventListener("mouseup", up);
189	  }, []);
190	
