194	    if (isNaN(p) || p < 0) {
195	      toast({ title: "Netinkama kaina", description: "Įveskite teigiamą skaičių.", variant: "destructive" });
196	      return;
197	    }
198	    setEntries(prev => {
199	      const next = new Map(prev);
