355	                        key={`lbl-${time}`}
356	                        className={`sticky left-0 z-10 bg-card border-r border-border flex items-center justify-end pr-2 text-[10px] text-muted-foreground tabular-nums ${isHourMark ? "border-t border-border" : ""}`}
357	                        style={{ height: 28 }}
