const extractApiError = (err: unknown, fallback: string): string => {
  if (err && typeof err === "object") {
    const e = err as Record<string, unknown>;
    const data = e["data"];
    if (data && typeof data === "object" && typeof (data as Record<string, unknown>)["error"] === "string") {
